50|    const onKey = (event: KeyboardEvent) => {
51|      if (event.metaKey || event.ctrlKey || event.altKey) return;
52|      const target = event.target as HTMLElement | null;
53|      if (
54|        target &&
55|        (target.tagName === "INPUT" ||
56|          target.tagName === "SELECT" ||
57|          target.tagName === "TEXTAREA" ||
58|          target.isContentEditable)
59|      ) {
60|        return;
61|      }
62|      if (event.key === "ArrowRight") {
63|        event.preventDefault();
