122|export interface NavState {
123|  sceneId: string;
124|  page: number;
125|}
126|
127|export type NavAction =
128|  | { kind: "next" }
129|  | { kind: "prev" }
130|  | { kind: "goto"; sceneId: string; atEnd?: boolean };
131|
132|export interface NavIndex {
133|  order: string[];
134|  pageCounts: Map<string, number>;
135|}
136|
137|export function buildNavIndex(views: { sceneId: string; pages: number }[]): NavIndex {
138|  return {
139|    order: views.map((v) => v.sceneId),
140|    pageCounts: new Map(views.map((v) => [v.sceneId, v.pages] as [string, number])),
141|  };
142|}
143|
144|// Every pager move in one place: next/prev cross scenes and chapters,
145|// going back lands on the last sub-page, bounds are no-ops, unknown
146|// goto ids keep state.
147|export function navReducer(state: NavState, action: NavAction, index: NavIndex): NavState {
148|  const at = index.order.indexOf(state.sceneId);
149|  if (at < 0) return state;
150|  const pages = index.pageCounts.get(state.sceneId) ?? 1;
151|  if (action.kind === "next") {
152|    if (state.page < pages - 1) return { ...state, page: state.page + 1 };
153|    const nextId = index.order[at + 1];
154|    return nextId === undefined ? state : { sceneId: nextId, page: 0 };
155|  }
156|  if (action.kind === "prev") {
157|    if (state.page > 0) return { ...state, page: state.page - 1 };
158|    const prevId = at > 0 ? index.order[at - 1] : undefined;
159|    if (prevId === undefined) return state;
160|    return { sceneId: prevId, page: (index.pageCounts.get(prevId) ?? 1) - 1 };
161|  }
162|  if (index.order.indexOf(action.sceneId) < 0) return state;
163|  const count = index.pageCounts.get(action.sceneId) ?? 1;
164|  return { sceneId: action.sceneId, page: action.atEnd ? count - 1 : 0 };
165|}
166|
167|// True only when the scene id changed. The container gates observeScene
168|// on this, so sub-page moves never touch the scheduler.
169|export function isSceneEntry(prevSceneId: string | null, nextSceneId: string): boolean {
170|  return prevSceneId !== nextSceneId;
171|}
172|
173|export function observeSceneEntry(
174|  prevSceneId: string | null,
175|  nextSceneId: string,
176|  observe: (sceneId: string) => void,
177|): void {
178|  if (isSceneEntry(prevSceneId, nextSceneId)) observe(nextSceneId);
179|}
180|
181|// Throws on unordered scenes and on paragraphs covered zero or two times.
182|export function buildReaderModel(
183|  book: Pick<Book, "id" | "title" | "author" | "chapters" | "paragraphs" | "textVersion">,
184|  analysis: { scenes: AnalyzedScene[] },
185|): ReaderModel {
186|  const byN = new Map(book.paragraphs.map((p) => [p.n, p]));
187|  const scenes = [...analysis.scenes];
188|  for (let i = 1; i < scenes.length; i++) {
189|    const prev = scenes[i - 1];
190|    const cur = scenes[i];
191|    if (prev && cur && (cur.start_n < prev.start_n || (cur.start_n === prev.start_n && cur.end_n < prev.end_n))) {
192|      throw new Error(`scenes out of order at ${cur.id}`);
193|    }
194|  }
195|  const seen = new Set<number>();
196|  const sceneParagraphs = new Map<string, ReaderParagraph[]>();
197|  for (const scene of scenes) {
198|    const paras: ReaderParagraph[] = [];
199|    for (let n = scene.start_n; n <= scene.end_n; n++) {
200|      const p = byN.get(n);
201|      if (!p) throw new Error(`scene ${scene.id} covers missing ordinal ${n}`);
202|      if (seen.has(n)) throw new Error(`ordinal ${n} covered twice`);
203|      seen.add(n);
204|      paras.push({ id: p.id, n: p.n, text: p.text });
205|    }
206|    sceneParagraphs.set(scene.id, paras);
207|  }
208|  if (seen.size !== book.paragraphs.length) {
209|    throw new Error(`coverage gap: ${book.paragraphs.length - seen.size} paragraphs uncovered`);
210|  }
211|  const chapters: ReaderChapter[] = book.chapters.map((chapter) => {
212|    const mine = scenes.filter((s) => s.ch === chapter.ch);
213|    if (mine.some((s) => s.start_n < chapter.start_n || s.end_n > chapter.end_n)) {
214|      throw new Error(`a scene crosses chapter ${chapter.ch} bounds`);
215|    }
216|    return {
217|      ch: chapter.ch,
218|      title: chapter.title,
219|      scenes: mine.map((s) => ({
220|        id: s.id,
221|        title: s.title,
222|        emotion: s.final === null ? null : { ...s.final },
223|        paragraphs: sceneParagraphs.get(s.id) ?? [],
224|      })),
225|    };
226|  });
227|  return {
228|    bookId: book.id,
229|    textVersion: book.textVersion,
230|    title: book.title,
231|    author: book.author,
232|    chapters,
233|  };
