102|    (sceneId: string) => {
103|      const st = liveRef.current;
104|      if (!st.manifest || !st.selection) return;
105|      const signal = st.byId.get(sceneId) ?? null;
106|      applyDecision(
107|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
108|          selection: st.selection,
109|          rng: Math.random,
110|        }, entryDwell()),
111|      );
112|    },
113|    [applyDecision],
114|  );
115|
116|  useEffect(() => {
117|    let cancelled = false;
