13|// One scene view: sub-pages, keys, buttons, progress, chapter jump.
14|// Sub-page moves stay in client state; scene moves push a new route.
15|export function ScenePage({ view, chapters }: { view: SceneView; chapters: ChapterJump[] }) {
16|  const router = useRouter();
17|  const atEnd = useSearchParams().get("at") === "end";
18|  const [page, setPage] = useState(atEnd ? view.pages.length - 1 : 0);
19|  const headingRef = useRef<HTMLHeadingElement>(null);
20|  const lastPage = view.pages.length - 1;
21|  const sub = view.pages[page] ?? view.pages[0];
22|  const atStart = view.prevSceneId === null && page === 0;
23|  const atBookEnd = view.nextSceneId === null && page === lastPage;
24|
25|  function goNext() {
26|    if (page < lastPage) {
27|      setPage(page + 1);
28|      window.scrollTo(0, 0);
29|      return;
30|    }
31|    if (view.nextSceneId) router.push(`/leer/${view.nextSceneId}`);
32|  }
33|
34|  function goPrev() {
35|    if (page > 0) {
36|      setPage(page - 1);
37|      window.scrollTo(0, 0);
38|      return;
39|    }
40|    if (view.prevSceneId) router.push(`/leer/${view.prevSceneId}?at=end`);
41|  }
42|
43|  // Scene entry resets orientation; sub-page moves keep the heading.
44|  useEffect(() => {
45|    headingRef.current?.focus();
46|    window.scrollTo(0, 0);
47|  }, [view.sceneId]);
48|
49|  useEffect(() => {
50|    const onKey = (event: KeyboardEvent) => {
51|      if (event.metaKey || event.ctrlKey || event.altKey) return;
52|      const target = event.target as HTMLElement | null;
53|      if (
54|        target &&
55|        (target.tagName === "INPUT" ||
56|          target.tagName === "SELECT" ||
57|          target.tagName === "TEXTAREA" ||
58|          target.isContentEditable)
59|      ) {
60|        return;
61|      }
62|      if (event.key === "ArrowRight") {
63|        event.preventDefault();
64|        goNext();
65|      } else if (event.key === "ArrowLeft") {
66|        event.preventDefault();
67|        goPrev();
68|      }
69|    };
70|    window.addEventListener("keydown", onKey);
71|    return () => window.removeEventListener("keydown", onKey);
72|  });
73|
74|  function jumpChapter(ch: number) {
75|    const found = chapters.find((c) => c.ch === ch);
76|    if (found && found.firstSceneId !== view.sceneId) router.push(`/leer/${found.firstSceneId}`);
