87|          {view.title}
88|        </h2>
89|        {sub?.paragraphs.map((p) => (
90|          <p key={p.id} id={p.id} data-n={p.n}>
91|            {p.text}
92|          </p>
93|        ))}
94|      </div>
95|      <nav className="scene-nav" aria-label="Escenas">
96|        <button type="button" onClick={goPrev} disabled={atStart} aria-label="Anterior">
97|          Anterior
98|        </button>
99|        <button type="button" onClick={goNext} disabled={atBookEnd} aria-label="Siguiente">
100|          Siguiente
101|        </button>
102|        <label className="scene-jump">
103|          Capítulo
104|          <select value={view.ch} onChange={(e) => jumpChapter(Number(e.target.value))} aria-label="Capítulo">
105|            {chapters.map((c) => (
106|              <option key={c.ch} value={c.ch}>
107|                {c.ch}. {c.title}
108|              </option>
109|            ))}
