35|
36|// Route entries use the short dwell; scoring and hysteresis are untouched.
37|function entryDwell(): { dwellSec: number } {
38|  return { dwellSec: MUSIC_CONFIG.sceneEntryDwellSec };
39|}
40|
41|// The Chopin playlist, when the manifest defines it with tracks. The
42|// button stays hidden otherwise, and the player never persists the mode.
43|function findChopinPlaylist(manifest: MusicManifest) {
