48|// Client container: cues music on scene entry only, from the route id.
49|// Sub-page moves never reach the scheduler. Params can lag a render, so
50|// the last observed id is compared before every observe call.
51|export function Reader({ scenes, children }: { scenes: SlimScene[]; children: React.ReactNode }) {
52|  const routeParams = useParams();
53|  const param = routeParams?.sceneId;
54|  const routeSceneId = typeof param === "string" ? param : null;
55|  const [manifest, setManifest] = useState<MusicManifest | null>(null);
56|  const [selection, setSelection] = useState<MusicSelection | null>(null);
57|  const [musicFailed, setMusicFailed] = useState(false);
58|  const [currentId, setCurrentId] = useState<string | null>(null);
59|  const [replayNonce, setReplayNonce] = useState(0);
60|  const [fadeSec, setFadeSec] = useState(0);
61|  const [isFallback, setIsFallback] = useState(false);
62|  const [playlistOn, setPlaylistOn] = useState(false);
63|  const byId = useMemo(() => new Map(scenes.map((s) => [s.id, s.emotion])), [scenes]);
64|  const schedRef = useRef<SchedulerState>(initScheduler());
65|  const observedRef = useRef<string | null>(null);
66|  const liveRef = useRef({ routeSceneId, manifest, selection, currentId, byId, playlistOn });
67|  liveRef.current = { routeSceneId, manifest, selection, currentId, byId, playlistOn };
68|
69|  const nowSec = () => Date.now() / 1000;
70|
71|  const applyDecision = useCallback((decision: {
72|    state: SchedulerState;
73|    switchToId: string | null;
74|    crossfadeSec: number;
75|    fallback: boolean;
76|  }) => {
77|    // A same-id switch (one-track playlist wrap) bails out of setCurrentId,
78|    // so bump a replay nonce the player effect listens to instead.
79|    const prevId = schedRef.current.currentId;
80|    schedRef.current = decision.state;
81|    setIsFallback(decision.fallback);
82|    if (decision.switchToId !== null) {
83|      setFadeSec(decision.crossfadeSec);
84|      if (decision.switchToId === prevId) {
85|        setReplayNonce((n) => n + 1);
86|      } else {
