88|      }
89|    }
90|  }, []);
91|
92|  const persist = useCallback((next: MusicSelection) => {
93|    setSelection(next);
94|    saveMusicPrefs({
95|      mode: next.mode,
96|      soundtrackId: next.soundtrackId,
97|      style: next.style,
98|    });
99|  }, []);
100|
101|  const observe = useCallback(
102|    (sceneId: string) => {
103|      const st = liveRef.current;
104|      if (!st.manifest || !st.selection) return;
105|      const signal = st.byId.get(sceneId) ?? null;
106|      applyDecision(
107|        observeScene(schedRef.current, sceneId, signal, st.manifest, nowSec(), {
108|          selection: st.selection,
109|          rng: Math.random,
110|        }, entryDwell()),
