119|      .then((res) => {
120|        if (!res.ok) throw new Error(`manifest ${res.status}`);
121|        return res.json();
122|      })
123|      .then((json: unknown) => {
124|        if (cancelled) return;
125|        const parsed = parseManifest(json);
126|        setManifest(parsed);
127|        setSelection(resolveInitialSelection(parsed, loadMusicPrefs()));
128|      })
129|      .catch(() => {
130|        if (!cancelled) setMusicFailed(true);
131|      });
132|    return () => {
133|      cancelled = true;
134|    };
135|  }, []);
136|
137|  // Scene entry: exactly one observe call per scene id, once the manifest
138|  // lands. The first scene cues at once, so it plays on the first press.
139|  useEffect(() => {
140|    if (!routeSceneId || !manifest || !isSceneEntry(observedRef.current, routeSceneId)) return;
141|    observedRef.current = routeSceneId;
142|    observe(routeSceneId);
143|  }, [routeSceneId, manifest, observe]);
