147|    const timer = window.setInterval(() => {
148|      const st = liveRef.current;
149|      if (!st.manifest || !st.selection || !st.routeSceneId) return;
150|      const sceneId = schedRef.current.pendingSceneId ?? st.routeSceneId;
151|      const signal = st.byId.get(sceneId) ?? null;
152|      applyDecision(
153|        tickScheduler(schedRef.current, signal, st.manifest, nowSec(), {
154|          selection: st.selection,
155|          rng: Math.random,
