160|  }, [applyDecision]);
161|
162|  function skip() {
163|    const st = liveRef.current;
164|    if (!st.manifest || !st.selection || !st.routeSceneId) return;
165|    const signal = st.byId.get(st.routeSceneId) ?? null;
166|    applyDecision(
167|      requestNext(schedRef.current, signal, st.manifest, nowSec(), {
168|        selection: st.selection,
169|        rng: Math.random,
170|      }),
171|    );
172|  }
173|
174|  function togglePlaylist() {
175|    const st = liveRef.current;
176|    if (!st.manifest || !st.selection) return;
