1|import { buildReaderModel } from "@/core/reader";
2|import { loadOzBook } from "@/server/books";
3|import { Reader } from "../reader";
4|
5|// Static shell: audio and music state persist across scene routes.
6|// Only slim metadata reaches the client: id, chapter, emotion triple.
7|export default function LeerLayout({ children }: { children: React.ReactNode }) {
8|  const { book, scenes } = loadOzBook();
9|  const model = buildReaderModel(book, { scenes });
10|  const slim = model.chapters.flatMap((chapter) =>
11|    chapter.scenes.map((scene) => ({ id: scene.id, ch: chapter.ch, emotion: scene.emotion })),
12|  );
13|  return (
14|    <>
15|      <header className="topbar">Lectoria</header>
16|      <Reader scenes={slim}>{children}</Reader>
17|    </>
18|  );
19|}

