1|import { describe, it } from "node:test";
2|import assert from "node:assert/strict";
3|import { checkIsolation, excerpt, normalize } from "./check-isolation.mjs";
4|
5|const own = "Dorothy lived in the midst of the great Kansas prairies, with Uncle Henry.";
6|const neighbor = "She was awakened by a shock, so sudden and severe that she was thrown.";
7|
8|function scenes() {
9|  return [
10|    { id: "s1", texts: [own] },
11|    { id: "s2", texts: [neighbor] },
12|  ];
13|}
14|
15|describe("checkIsolation", () => {
16|  it("passes when each route carries only its own text", () => {
17|    const readFile = (path) => (path.includes("s1") ? `<p>${own}</p>` : `<p>${neighbor}</p>`);
18|    const filesFor = (id) => [`/out/${id}.html`];
19|    assert.deepEqual(checkIsolation({ scenes: scenes(), readFile, filesFor }), []);
20|  });
21|
22|  it("fails when a route carries neighbor text, and on blind scans", () => {
23|    const leaked = `<p>${own}</p><p>${neighbor}</p>`;
24|    assert.match(
25|      checkIsolation({ scenes: scenes(), readFile: () => leaked, filesFor: (id) => [`/out/${id}.html`] }).join("\n"),
26|      /s1: leaks text of neighbor s2/,
27|    );
28|    assert.match(
29|      checkIsolation({ scenes: scenes(), readFile: () => "<p>other words entirely here</p>", filesFor: (id) => [`/out/${id}.html`] }).join("\n"),
30|      /own text missing/,
31|    );
32|  });
33|
34|  it("sees through JSON and HTML escaping", () => {
35|    assert.equal(normalize("farmer\\u2019s wife\\nnext"), normalize("farmer’s wife next"));
36|    assert.equal(normalize("farmer&#x27;s wife"), normalize("farmer’s wife"));
37|    assert.ok(excerpt(own).length >= 40);
38|  });
39|});

